class Task:
    def __init__(self, C_i, S_i, D_i, T_i, alpha_u_i_func):
        self.C = C_i
        self.S = S_i
        self.D = D_i
        self.T = T_i
        self.alpha_u = alpha_u_i_func # Function: delta -> num_releases

    def calculate_C_star(self, R_i):
        # R_i must be known or estimated
        return min(self.alpha_u(R_i) * self.C, R_i)

# Example alpha_u for sporadic task:
def sporadic_alpha_u(delta, T_i):
    if delta < 0: return 0
    if T_i == 0: return float('inf') # Or handle as burst
    return math.ceil(delta / T_i) # Simplified for integer jobs

# Check sub-additivity (conceptual)
def is_sub_additive(alpha_u_func):
