def is_suspension_aware_busy_interval(interval_start, interval_end, task_k, schedule):
    # Check if task_k has pending workload (ready or suspended) throughout the interval
    for t in range(interval_start, interval_end):
        if not schedule.has_pending_workload(task_k, t):
            return False
    return True

def find_a_th_job_in_busy_interval(task_k, job_index, schedule):
    job_k_a = task_k.jobs[job_index]
    # Find r_k_minus_a_plus_1: release of the first job in the current busy interval
    # This is a complex procedure involving iterating backwards from job_k_a
    # and checking if previous jobs complete before the current busy interval starts.
    # For simplicity, assume r_k_minus_a_plus_1 is given by the analysis context.
    r_k_minus_a_plus_1 = calculate_busy_interval_start(task_k, job_k_a, schedule)

    if is_suspension_aware_busy_interval(r_k_minus_a_plus_1, job_k_a.finish_time, task_k, schedule):
        return job_k_a, r_k_minus_a_plus_1
    return None

def calculate_interval_metrics(interval_start, interval_end, schedule_psi_1, task_set):
    idle_time = 0
    exec_time = 0
    exec_i_times = {task.id: 0 for task in task_set}

    for t in range(interval_start, interval_end): # Assuming discrete time units
        if schedule_psi_1.is_idle(t):
            idle_time += 1
        else:
            exec_time += 1
            executing_task_id = schedule_psi_1.get_executing_task(t)
            if executing_task_id is not None:
                exec_i_times[executing_task_id] += 1

    # Check consistency
    assert exec_time == sum(exec_i_times.values())

    return idle_time, exec_time, exec_i_times

def is_work_conserving(schedule, task_set):
    for t in range(0, schedule.total_time):
        pending_work_exists = False
        for task_i in task_set:
            if schedule.has_pending_workload(task_i, t):
                pending_work_exists = True
                break

        if pending_work_exists:
            if schedule.is_idle(t):
                # Check if the idle time is due to a task's self-suspension
                # This requires more detailed schedule state
                # For this definition, it means no task is ready AND no task is suspending
                # If a task is suspending, it's not 'idle' in the sense of no work.
                # The definition implies that if pending work exists, processor is busy or task suspends.
                # So, if processor is idle, no pending work should exist.
                if not schedule.is_any_task_suspending(t):
                    return False # Processor is idle but work is pending and no suspension
    return True

def calculate_interference_in_interval(task_i, t_start, delta, schedule):
    interference = 0
    t_end = t_start + delta
    for job in task_i.jobs:
        if t_start <= job.release_time < t_end:
            # Sum execution time of this job within [t_start, t_end)
            # This is simplified; actual execution might be spread out
            interference += job.execution_time_in_interval(t_start, t_end)
    return interference

def calculate_max_interference_curve(task_i, delta_max):
    I_u_i_curve = {}
    for delta in range(0, delta_max + 1):
        max_val = 0
        # This sup_t is usually found by analyzing critical instants or using arrival curves
        # For a given delta, I_u_i(delta) is often alpha_u_i(delta) * C_i
        max_val = task_i.alpha_u(delta) * task_i.C # Simplified based on Lemma 13(2)
        I_u_i_curve[delta] = max_val
    return I_u_i_curve

def calculate_t_star_values(t_values, x_values, idle_func, k_task_index):
    t_star = [0] * (k_task_index + 1) # t_star[0] unused, t_star[1] to t_star[k]
    t_star[1] = t_values[1] # t_1

    for i in range(2, k_task_index + 1):
        # x_values[i-1] corresponds to task tau_{i-1}
        # idle_func(t_values[i-1], t_values[i]) is idle time between t_{i-1} and t_i
        t_star[i] = t_star[i-1] + x_values[i-1] * idle_func(t_values[i-1], t_values[i])
    return t_star

def calculate_A1_i(task_i, R_i, delta):
    return task_i.alpha_u(delta + max(R_i - task_i.T, 0)) * task_i.C

def calculate_A0_i(task_i, R_i, C_star_i, delta):
    bound1 = task_i.alpha_u(delta + R_i) * task_i.C
    bound2 = task_i.alpha_u(delta - task_i.T + R_i - C_star_i) * task_i.C + C_star_i
    return min(bound1, bound2)

def verify_lemma_8(schedule_psi_1, task_set, t_values, f_k_a, k_task_index):
    # Part 1: For higher priority tasks
    for i in range(1, k_task_index):
        interval_start = t_values[i]
        interval_end = t_values[i+1]
        for t in range(interval_start, interval_end):
            if schedule_psi_1.is_idle(t):
                # If idle, it must be because task tau_i is suspending
                assert schedule_psi_1.is_task_suspending(task_set[i], t)
            else:
                # If not idle, either tau_i or a higher priority task is executing
                executing_task = schedule_psi_1.get_executing_task(t)
                assert executing_task.priority <= task_set[i].priority

    # Part 2: For task tau_k
    interval_start = t_values[k_task_index] # t_k
    interval_end = f_k_a
    for t in range(interval_start, interval_end):
        if schedule_psi_1.is_idle(t):
            # If idle, it must be because task tau_k is suspending
            assert schedule_psi_1.is_task_suspending(task_set[k_task_index], t)
        else:
            # If not idle, either tau_k or a higher priority task is executing
            executing_task = schedule_psi_1.get_executing_task(t)
            assert executing_task.priority <= task_set[k_task_index].priority

def verify_lemma_10(task_k, t_k, current_t, a_jobs, S_k, schedule_psi_1):
    actual_idle_time = calculate_interval_metrics(t_k, current_t, schedule_psi_1, [task_k])[0]
    assert actual_idle_time <= a_jobs * S_k

def verify_lemma_13_property1(I_u_i_func, delta, delta_prime):
    assert I_u_i_func(delta) <= I_u_i_func(delta - delta_prime) + delta_prime

def verify_lemma_13_property2(I_u_i_func, alpha_u_i_func, C_i, delta):
    assert I_u_i_func(delta) <= alpha_u_i_func(delta) * C_i

def calculate_exec_bound_lemma_14(task_i, R_i, delta):
    # This is identical to the A1_i definition
    return task_i.alpha_u(delta + max(R_i - task_i.T, 0)) * task_i.C

def calculate_exec_bound_lemma_15(task_i, R_i, C_star_i, delta):
    # This is part of the A0_i definition
    return task_i.alpha_u(delta - task_i.T + R_i - C_star_i) * task_i.C + C_star_i

def verify_lemma_16(task_k, t_k, current_t, a_jobs, C_k, schedule_psi_1):
    actual_exec_time = calculate_interval_metrics(t_k, current_t, schedule_psi_1, [task_k])[2][task_k.id]
    assert actual_exec_time <= a_jobs * C_k

def verify_lemma_20(t_star_values, t_values, k_task_index):
    for i in range(1, k_task_index + 1):
        assert t_star_values[i] <= t_values[i]
